%[text] %[text:anchor:H_F381D287] # Generation of a quadratic one-dimensional mesh generation along line
%[text] It returns an one-dimensional quadratic three-noded mesh along a line:
%[text]{"align":"center"} ![map_to_biunit_domain_quadratic.png](text:image:49e0)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function msh = generateQuadraticMeshOnLine(mshL1)
%[text] %[text:anchor:H_DB71A4FF] ## **Function Description**
%[text] Returns a structure containing the nodes and the elements on a line corresponding to an one-dimensional quadratic three-noded mesh based on an existing one-dimensional linear two-noded mesh.
%[text]  **Input :**
%[text]  `mshL1` : The one-dimensional linear mesh using two-noded elements as a structure with the following fields:
%[text]                             .nodes : Number of nodes in the one-dimensional mesh
%[text]                        .elements : Number of elements in the one-dimensional mesh
%[text]  **Output :**
%[text]  `msh` : The one-dimensional quadratic mesh using three-noded elements as a structure with the following fields:
%[text]                              .`nodes` : Number of nodes in the one-dimensional mesh
%[text]                        .`elements` : Number of elements in the one-dimensional mesh
%[text] %[text:anchor:H_1FDD3DB8] ## Function Implementation
%[text] %[text:anchor:H_2340AC29] ### Input validation
    arguments
        mshL1 (1, 1) {mustHaveNodesAndElements}
    end
%[text] %[text:anchor:H_3C1763A7] ### Mesh generation
    msh.nodes = zeros(numel(mshL1.nodes(:, 1)) + numel(mshL1.elements(:, 1)), 1);
    msh.nodes(1:numel(mshL1.nodes(:, 1))) = mshL1.nodes(:, 1);
    for ii = 1:numel(mshL1.elements(:, 1))
        nodes_el_L1 = mshL1.nodes(mshL1.elements(ii, :));
        msh.nodes(numel(mshL1.nodes(:, 1)) + ii, 1) = mean(nodes_el_L1);
    end
    msh.elements = horzcat(mshL1.elements, transpose(numel(mshL1.nodes(:, 1)) + ...
        1:numel(mshL1.nodes(:, 1)) + numel(mshL1.elements(:, 1))));
%[text] 
end

